ALTER TABLE public.work_stages ADD COLUMN IF NOT EXISTS scope_services text, ADD COLUMN IF NOT EXISTS schedule_change_reason text;
ALTER TABLE public.work_registry ADD COLUMN IF NOT EXISTS schedule_notes text, ADD COLUMN IF NOT EXISTS schedule_change_reason text;
CREATE TABLE public.work_schedule_versions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), work_id uuid NOT NULL REFERENCES public.work_registry(id), version integer NOT NULL, stages jsonb NOT NULL, notes text, reason text NOT NULL, created_by uuid DEFAULT auth.uid(), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(work_id,version));
GRANT SELECT ON public.work_schedule_versions TO authenticated;
GRANT ALL ON public.work_schedule_versions TO service_role;
ALTER TABLE public.work_schedule_versions ENABLE ROW LEVEL SECURITY;
CREATE POLICY schedule_version_read ON public.work_schedule_versions FOR SELECT TO authenticated USING (public.can_see_costs(auth.uid()) OR public.has_role(auth.uid(),'equipe'));
CREATE OR REPLACE FUNCTION public.guard_stage_dependency() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ DECLARE dep public.work_stages; cycle boolean; BEGIN PERFORM id FROM public.work_registry WHERE id=new.work_id FOR UPDATE; IF new.planned_end<new.planned_start OR new.actual_end<new.actual_start THEN RAISE EXCEPTION 'Término anterior ao início.'; END IF; IF new.dependency_id IS NOT NULL THEN SELECT * INTO dep FROM public.work_stages WHERE id=new.dependency_id; IF NOT FOUND OR dep.work_id<>new.work_id OR dep.id=new.id THEN RAISE EXCEPTION 'Dependência inválida.'; END IF; WITH RECURSIVE chain AS (SELECT id,dependency_id FROM public.work_stages WHERE id=new.dependency_id UNION SELECT s.id,s.dependency_id FROM public.work_stages s JOIN chain c ON s.id=c.dependency_id) SELECT exists(SELECT 1 FROM chain WHERE id=new.id) INTO cycle; IF cycle THEN RAISE EXCEPTION 'Dependência circular.'; END IF; END IF; RETURN new; END $$;
CREATE FUNCTION public.capture_schedule_version(_work_id uuid,_reason text) RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE v integer; snapshot jsonb; BEGIN PERFORM id FROM public.work_registry WHERE id=_work_id FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Obra não encontrada.'; END IF; SELECT coalesce(max(version),0)+1 INTO v FROM public.work_schedule_versions WHERE work_id=_work_id; SELECT coalesce(jsonb_agg(jsonb_build_object('id',s.id,'name',s.name,'sort',s.sort,'planned_start',s.planned_start,'planned_end',s.planned_end,'responsible',s.responsible,'observations',s.observations,'scope_services',s.scope_services,'weight',s.weight,'dependency_id',s.dependency_id) ORDER BY s.sort,s.id),'[]'::jsonb) INTO snapshot FROM public.work_stages s WHERE s.work_id=_work_id; INSERT INTO public.work_schedule_versions(work_id,version,stages,notes,reason) SELECT _work_id,v,snapshot,schedule_notes,_reason FROM public.work_registry WHERE id=_work_id; RETURN v; END $$;
REVOKE ALL ON FUNCTION public.capture_schedule_version(uuid,text) FROM PUBLIC,anon,authenticated;
CREATE FUNCTION public.schedule_planning_history() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE wid uuid; changed boolean; reason text; BEGIN IF tg_table_name='work_stages' THEN wid:=new.work_id; changed:=tg_op='INSERT'; IF tg_op='UPDATE' THEN changed:=ROW(new.name,new.sort,new.planned_start,new.planned_end,new.responsible,new.observations,new.scope_services,new.weight,new.dependency_id) IS DISTINCT FROM ROW(old.name,old.sort,old.planned_start,old.planned_end,old.responsible,old.observations,old.scope_services,old.weight,old.dependency_id); END IF; ELSE wid:=new.id; changed:=new.schedule_notes IS DISTINCT FROM old.schedule_notes; END IF; PERFORM id FROM public.work_registry WHERE id=wid FOR UPDATE; IF changed AND exists(SELECT 1 FROM public.work_schedule_versions WHERE work_id=wid) AND coalesce(current_setting('jmg.schedule_batch',true),'')<>'on' THEN reason:=nullif(trim(new.schedule_change_reason),''); IF reason IS NULL THEN RAISE EXCEPTION 'Informe o motivo da reprogramação.'; END IF; PERFORM public.capture_schedule_version(wid,reason); END IF; RETURN new; END $$;
CREATE TRIGGER schedule_stage_history AFTER INSERT OR UPDATE ON public.work_stages FOR EACH ROW EXECUTE FUNCTION public.schedule_planning_history();
CREATE TRIGGER schedule_notes_history AFTER UPDATE OF schedule_notes ON public.work_registry FOR EACH ROW EXECUTE FUNCTION public.schedule_planning_history();
CREATE FUNCTION public.approve_work_schedule(_work_id uuid) RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.can_see_costs(auth.uid()) THEN RAISE EXCEPTION 'Sem permissão'; END IF; PERFORM id FROM public.work_registry WHERE id=_work_id FOR UPDATE; IF EXISTS(SELECT 1 FROM public.work_schedule_versions WHERE work_id=_work_id) THEN RAISE EXCEPTION 'Cronograma original já preservado.'; END IF; IF NOT EXISTS(SELECT 1 FROM public.work_stages WHERE work_id=_work_id) OR EXISTS(SELECT 1 FROM public.work_stages WHERE work_id=_work_id AND (planned_start IS NULL OR planned_end IS NULL)) THEN RAISE EXCEPTION 'Informe início e término previstos de todas as etapas.'; END IF; RETURN public.capture_schedule_version(_work_id,'Cronograma original aprovado'); END $$;
REVOKE ALL ON FUNCTION public.approve_work_schedule(uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.approve_work_schedule(uuid) TO authenticated;
CREATE FUNCTION public.import_work_schedule(_work_id uuid) RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE bid uuid; n integer; BEGIN IF NOT public.can_see_costs(auth.uid()) THEN RAISE EXCEPTION 'Sem permissão'; END IF; SELECT linked_budget_id INTO bid FROM public.work_registry WHERE id=_work_id FOR UPDATE; IF NOT FOUND OR bid IS NULL THEN RAISE EXCEPTION 'Obra sem orçamento vinculado: cadastre as etapas manualmente.'; END IF; IF NOT EXISTS(SELECT 1 FROM public.budgets WHERE id=bid AND status='aprovado') THEN RAISE EXCEPTION 'Orçamento vinculado não aprovado.'; END IF; INSERT INTO public.work_stages(work_id,budget_section_id,name,sort,scope_services,observations,schedule_change_reason) SELECT _work_id,bs.id,bs.title,bs.sort,(SELECT string_agg(bi.description,E'\n' ORDER BY bi.sort,bi.id) FROM public.budget_items bi WHERE bi.section_id=bs.id AND bi.budget_id=bid),bs.materials_text,'Importação do escopo aprovado' FROM public.budget_sections bs WHERE bs.budget_id=bid AND NOT EXISTS(SELECT 1 FROM public.work_stages s WHERE s.work_id=_work_id AND s.budget_section_id=bs.id); GET DIAGNOSTICS n=ROW_COUNT; UPDATE public.work_stages s SET scope_services=(SELECT string_agg(bi.description,E'\n' ORDER BY bi.sort,bi.id) FROM public.budget_items bi WHERE bi.section_id=s.budget_section_id AND bi.budget_id=bid),schedule_change_reason='Importação dos serviços aprovados' WHERE s.work_id=_work_id AND s.budget_section_id IS NOT NULL AND s.scope_services IS NULL; RETURN n; END $$;
REVOKE ALL ON FUNCTION public.import_work_schedule(uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.import_work_schedule(uuid) TO authenticated;
CREATE FUNCTION public.reorder_work_schedule(_work_id uuid,_ids uuid[],_reason text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE n integer; BEGIN IF NOT public.can_see_costs(auth.uid()) THEN RAISE EXCEPTION 'Sem permissão'; END IF; PERFORM id FROM public.work_registry WHERE id=_work_id FOR UPDATE; SELECT count(*) INTO n FROM public.work_stages WHERE work_id=_work_id; IF cardinality(_ids)<>n OR (SELECT count(DISTINCT x) FROM unnest(_ids) x)<>n OR EXISTS(SELECT 1 FROM unnest(_ids) x WHERE NOT EXISTS(SELECT 1 FROM public.work_stages WHERE work_id=_work_id AND id=x)) THEN RAISE EXCEPTION 'Ordem inválida.'; END IF; IF EXISTS(SELECT 1 FROM public.work_schedule_versions WHERE work_id=_work_id) AND nullif(trim(_reason),'') IS NULL THEN RAISE EXCEPTION 'Informe o motivo da reprogramação.'; END IF; PERFORM set_config('jmg.schedule_batch','on',true); UPDATE public.work_stages s SET sort=u.ordinality-1,schedule_change_reason=_reason FROM unnest(_ids) WITH ORDINALITY AS u(id,ordinality) WHERE s.id=u.id AND s.work_id=_work_id; PERFORM set_config('jmg.schedule_batch','off',true); IF EXISTS(SELECT 1 FROM public.work_schedule_versions WHERE work_id=_work_id) THEN PERFORM public.capture_schedule_version(_work_id,_reason); END IF; END $$;
REVOKE ALL ON FUNCTION public.reorder_work_schedule(uuid,uuid[],text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.reorder_work_schedule(uuid,uuid[],text) TO authenticated;